package com.saroj.lmsmobile.api

import com.saroj.lmsmobile.data.models.auth.LoginRequest
import com.saroj.lmsmobile.data.models.auth.LoginResponse
import com.saroj.lmsmobile.data.models.auth.ProfileResponse
import com.saroj.lmsmobile.data.models.book.Book
import com.saroj.lmsmobile.data.models.common.PaginatedResponse
import com.saroj.lmsmobile.data.models.dashboard.DashboardResponse
import com.saroj.lmsmobile.data.models.fine.Fine
import com.saroj.lmsmobile.data.models.issue.Issue
import com.saroj.lmsmobile.data.models.issue.IssueRequest
import com.saroj.lmsmobile.data.models.student.Student
import retrofit2.Response
import retrofit2.http.*

/**
 * ApiService defines all REST API endpoints for the LMS Mobile App.
 * This interface is implemented by Retrofit at runtime.
 *
 * Features:
 * - Authentication endpoints
 * - Book management endpoints
 * - Student management endpoints
 * - Issue/Borrowing endpoints
 * - Fine management endpoints
 * - Dashboard endpoints
 *
 * All protected endpoints automatically receive Bearer token via AuthInterceptor.
 *
 * Usage:
 *   val apiService = RetrofitClient.getApiService(tokenManager)
 *   try {
 *       val response = apiService.login(LoginRequest(...))
 *       // Handle response
 *   } catch (e: Exception) {
 *       // Handle error
 *   }
 */
interface ApiService {

    // ==================== AUTHENTICATION ====================

    /**
     * Login with email and password.
     * Returns access token and user information.
     */
    @POST("login")
    suspend fun login(@Body request: LoginRequest): Response<LoginResponse>

    /**
     * Logout and invalidate current token.
     */
    @POST("logout")
    suspend fun logout(): Response<Any>

    /**
     * Get current logged-in user profile.
     */
    @GET("profile")
    suspend fun getProfile(): Response<ProfileResponse>

    /**
     * Test endpoint to verify if token is valid (returns 401 if invalid).
     */
    @GET("test-unauthorized")
    suspend fun testUnauthorized(): Response<Any>

    // ==================== BOOKS ====================

    /**
     * Get all available books with pagination.
     * @param page Page number (default: 1)
     * @param pageSize Items per page (default: 20)
     */
    @GET("books")
    suspend fun getBooks(
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Book>>

    /**
     * Get book details by ID.
     * @param id Book ID
     */
    @GET("books/{id}")
    suspend fun getBookDetail(@Path("id") id: Int): Response<Book>

    /**
     * Search books by query string.
     * @param query Search keyword (title, author, ISBN)
     */
    @GET("books/search")
    suspend fun searchBooks(@Query("q") query: String): Response<PaginatedResponse<Book>>

    /**
     * Get all available books (not currently issued).
     */
    @GET("books/available")
    suspend fun getAvailableBooks(
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Book>>

    /**
     * Get books by category.
     * @param category Category name or ID
     */
    @GET("books/category/{category}")
    suspend fun getBooksByCategory(
        @Path("category") category: String,
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Book>>

    // ==================== STUDENTS ====================

    /**
     * Get all students (Admin & Staff only).
     */
    @GET("students")
    suspend fun getStudents(
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Student>>

    /**
     * Get student details by ID.
     * @param id Student ID
     */
    @GET("students/{id}")
    suspend fun getStudentDetail(@Path("id") id: Int): Response<Student>

    /**
     * Search students by query string.
     * @param query Search keyword (name, email, student ID)
     */
    @GET("students/search")
    suspend fun searchStudents(
        @Query("q") query: String,
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Student>>

    // ==================== ISSUES (Book Borrowing) ====================

    /**
     * Get all book issues/borrowing records.
     */
    @GET("issues")
    suspend fun getIssues(
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Issue>>

    /**
     * Get issue details by ID.
     * @param id Issue ID
     */
    @GET("issues/{id}")
    suspend fun getIssueDetail(@Path("id") id: Int): Response<Issue>

    /**
     * Create a new book issue (issue a book to a student).
     */
    @POST("issues")
    suspend fun createIssue(@Body request: IssueRequest): Response<Issue>

    /**
     * Mark book as returned.
     * @param id Issue ID
     */
    @POST("issues/return/{id}")
    suspend fun returnBook(@Path("id") id: Int): Response<Issue>

    /**
     * Get all issues for a specific student.
     * @param studentId Student ID
     */
    @GET("issues/student/{studentId}")
    suspend fun getStudentIssues(
        @Path("studentId") studentId: Int,
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Issue>>

    // ==================== DASHBOARD ====================

    /**
     * Get dashboard statistics and summary data.
     * Content varies based on user role (Admin/Staff/Student).
     */
    @GET("dashboard")
    suspend fun getDashboard(): Response<DashboardResponse>

    // ==================== OVERDUE ====================

    /**
     * Get all overdue book issues.
     */
    @GET("overdue")
    suspend fun getOverdueIssues(
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Issue>>

    // ==================== FINES ====================

    /**
     * Get all fines.
     */
    @GET("fines")
    suspend fun getFines(
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Fine>>

    /**
     * Get all fines for a specific student.
     * @param studentId Student ID
     */
    @GET("fines/student/{studentId}")
    suspend fun getStudentFines(
        @Path("studentId") studentId: Int,
        @Query("page") page: Int = 1,
        @Query("per_page") pageSize: Int = 20
    ): Response<PaginatedResponse<Fine>>
}

package com.saroj.lmsmobile.api

import com.google.gson.Gson
import com.google.gson.GsonBuilder
import com.saroj.lmsmobile.api.interceptor.AuthInterceptor
import com.saroj.lmsmobile.storage.TokenManager
import com.saroj.lmsmobile.utils.Constants
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import java.util.concurrent.TimeUnit

/**
 * RetrofitClient provides a singleton instance of Retrofit for API communication.
 *
 * Features:
 * - Singleton pattern (lazy initialization)
 * - OkHttpClient with custom configuration
 * - HttpLoggingInterceptor for debugging (debug builds only)
 * - AuthInterceptor for automatic token attachment
 * - Timeout configuration
 * - Gson converter with proper settings
 *
 * Usage:
 *   val apiService = RetrofitClient.getApiService(context)
 *   val books = apiService.getBooks()
 *
 * Architecture:
 *   Request → AuthInterceptor (adds token) → HttpLogging (logs request)
 *   → OkHttpClient → Server
 *   Response → HttpLogging (logs response) → Retrofit → ViewModel
 */
object RetrofitClient {

    private var retrofit: Retrofit? = null
    private var apiService: ApiService? = null

    /**
     * Gets or creates the Retrofit instance.
     * @param tokenManager TokenManager for authentication
     * @return Retrofit instance configured with OkHttpClient
     */
    private fun getRetrofit(tokenManager: TokenManager): Retrofit {
        return retrofit ?: createRetrofit(tokenManager).also { retrofit = it }
    }

    /**
     * Gets or creates the ApiService instance.
     * @param tokenManager TokenManager for authentication
     * @return ApiService interface implementation
     */
    fun getApiService(tokenManager: TokenManager): ApiService {
        return apiService ?: getRetrofit(tokenManager).create(ApiService::class.java).also {
            apiService = it
        }
    }

    /**
     * Creates a new Retrofit instance with full configuration.
     */
    private fun createRetrofit(tokenManager: TokenManager): Retrofit {
        return Retrofit.Builder()
            .baseUrl(Constants.BASE_URL)
            .client(createOkHttpClient(tokenManager))
            .addConverterFactory(createGsonConverterFactory())
            .build()
    }

    /**
     * Creates OkHttpClient with logging and authentication interceptors.
     */
    private fun createOkHttpClient(tokenManager: TokenManager): OkHttpClient {
        val builder = OkHttpClient.Builder()

        // Add Auth Interceptor (adds Bearer token to all requests)
        builder.addInterceptor(AuthInterceptor(tokenManager))

        // Add HttpLogging Interceptor (only in debug builds)
        val httpLoggingInterceptor = HttpLoggingInterceptor().apply {
            level = HttpLoggingInterceptor.Level.BODY
        }
        builder.addInterceptor(httpLoggingInterceptor)

        // Set timeouts
        builder.connectTimeout(Constants.CONNECT_TIMEOUT, TimeUnit.SECONDS)
        builder.readTimeout(Constants.READ_TIMEOUT, TimeUnit.SECONDS)
        builder.writeTimeout(Constants.CONNECT_TIMEOUT, TimeUnit.SECONDS)

        return builder.build()
    }

    /**
     * Creates Gson converter factory with proper settings.
     */
    private fun createGsonConverterFactory(): GsonConverterFactory {
        val gson = GsonBuilder()
            .setLenient()
            .setPrettyPrinting()
            .create()

        return GsonConverterFactory.create(gson)
    }

    /**
     * Resets the Retrofit instance (useful for switching base URL or token).
     * Call this if you need to reinitialize Retrofit with new configuration.
     */
    fun reset() {
        retrofit = null
        apiService = null
    }
}

package com.saroj.lmsmobile.api.interceptor

import com.saroj.lmsmobile.storage.TokenManager
import com.saroj.lmsmobile.utils.Constants
import kotlinx.coroutines.flow.firstOrNull
import kotlinx.coroutines.runBlocking
import okhttp3.Interceptor
import okhttp3.Response

/**
 * AuthInterceptor automatically adds Bearer token to all API requests.
 *
 * Features:
 * - Retrieves token from DataStore
 * - Adds Authorization header with Bearer token
 * - Handles requests without token gracefully
 * - Provides proper error responses for 401 (Unauthorized)
 *
 * Flow:
 * 1. Interceptor intercepts every request
 * 2. Gets token from TokenManager
 * 3. Adds "Authorization: Bearer <token>" header
 * 4. Proceeds with request
 * 5. Returns response (or 401 if token invalid)
 *
 * Usage:
 *   val interceptor = AuthInterceptor(tokenManager)
 *   val client = OkHttpClient.Builder()
 *       .addInterceptor(interceptor)
 *       .build()
 */
class AuthInterceptor(private val tokenManager: TokenManager) : Interceptor {

    override fun intercept(chain: Interceptor.Chain): Response {
        val originalRequest = chain.request()

        // Get token from DataStore (blocking because OkHttp is synchronous)
        val token = runBlocking {
            tokenManager.getToken().firstOrNull()
        }

        // If no token, proceed with original request
        if (token.isNullOrEmpty()) {
            return chain.proceed(originalRequest)
        }

        // Build new request with Authorization header
        val newRequest = originalRequest.newBuilder().apply {
            addHeader(Constants.AUTHORIZATION_HEADER, "${Constants.BEARER_TOKEN_PREFIX}$token")
            addHeader(Constants.ACCEPT_HEADER, Constants.APPLICATION_JSON)
            addHeader(Constants.CONTENT_TYPE_HEADER, Constants.APPLICATION_JSON)
        }.build()

        return chain.proceed(newRequest)
    }
}

package com.saroj.lmsmobile.data.models.auth
import com.google.gson.annotations.SerializedName
/** * LoginRequest represents the login API request body. */ data class LoginRequest( val email: String, val password: String )
/** * LoginResponse represents the server response after successful login. * Contains the access token and user information. */ data class LoginResponse( val message: String? = null, val access_token: String, val token_type: String = "Bearer", val user: User )
/** * User represents a user in the system. * Shared model used across login response and profile. */ data class User( val id: Int, val name: String, val email: String, @SerializedName("role") val role: String, @SerializedName("created_at") val createdAt: String? = null, @SerializedName("updated_at") val updatedAt: String? = null )
/** * ProfileResponse represents the profile API response. * Contains detailed user information. */ data class ProfileResponse( val message: String? = null, val user: User )

package com.saroj.lmsmobile.data.models.common

/**
 * Sealed class to handle network responses uniformly across the app.
 * Provides a clean way to represent Success, Error, Loading, and Unauthorized states.
 *
 * Usage in Repository:
 *   return try {
 *       val response = apiService.getBooks()
 *       NetworkResult.Success(response)
 *   } catch (e: Exception) {
 *       NetworkResult.Error("Failed to fetch books", null)
 *   }
 *
 * Usage in ViewModel:
 *   repository.getBooks().collect { result ->
 *       when (result) {
 *           is NetworkResult.Success -> { ... }
 *           is NetworkResult.Error -> { ... }
 *           is NetworkResult.Loading -> { ... }
 *           is NetworkResult.Unauthorized -> { ... }
 *       }
 *   }
 */
sealed class NetworkResult<T> {

    /**
     * Success state with data of type T.
     * @param data The successful response data
     */
    data class Success<T>(val data: T) : NetworkResult<T>()

    /**
     * Error state with error message and optional HTTP status code.
     * @param message Human-readable error message
     * @param code HTTP status code (e.g., 404, 422, 500)
     */
    data class Error<T>(
        val message: String,
        val code: Int? = null
    ) : NetworkResult<T>()

    /**
     * Loading state - represents an ongoing network request.
     */
    class Loading<T> : NetworkResult<T>()

    /**
     * Unauthorized state - represents 401 responses (expired token, not authenticated).
     * Use this to trigger logout and redirect to login screen.
     */
    class Unauthorized<T> : NetworkResult<T>()
}

/**
 * Extension function to safely map success data.
 * Usage: result.mapSuccess { it.data }
 */
inline fun <T, R> NetworkResult<T>.mapSuccess(block: (T) -> R): NetworkResult<R> {
    return when (this) {
        is NetworkResult.Success -> NetworkResult.Success(block(this.data))
        is NetworkResult.Error -> NetworkResult.Error(this.message, this.code)
        is NetworkResult.Loading -> NetworkResult.Loading()
        is NetworkResult.Unauthorized -> NetworkResult.Unauthorized()
    }
}

/**
 * Extension function to handle all cases with a block.
 * Usage: result.handle(
 *     onSuccess = { ... },
 *     onError = { message, code -> ... }
 * )
 */
inline fun <T> NetworkResult<T>.handle(
    onSuccess: (T) -> Unit,
    onError: (String, Int?) -> Unit,
    onLoading: () -> Unit = {},
    onUnauthorized: () -> Unit = {}
) {
    when (this) {
        is NetworkResult.Success -> onSuccess(this.data)
        is NetworkResult.Error -> onError(this.message, this.code)
        is NetworkResult.Loading -> onLoading()
        is NetworkResult.Unauthorized -> onUnauthorized()
    }
}

package com.saroj.lmsmobile.storage

import android.content.Context
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.booleanPreferencesKey
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import com.saroj.lmsmobile.utils.Constants
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

/**
 * TokenManager handles all token and session storage using DataStore Preferences.
 * Provides secure, encrypted storage for user credentials and session information.
 *
 * Features:
 * - Save and retrieve authentication token
 * - Store user information (ID, name, email, role)
 * - Clear all data on logout
 * - Observe token changes in real-time
 *
 * Usage:
 *   val tokenManager = TokenManager(context)
 *   tokenManager.saveToken("Bearer token_here")
 *   tokenManager.getToken().collect { token -> ... }
 */
private val Context.dataStore: DataStore<Preferences> by preferencesDataStore(
    name = "lms_mobile_app_prefs"
)

class TokenManager(private val context: Context) {

    private object PrefsKeys {
        val TOKEN = stringPreferencesKey(Constants.TOKEN_KEY)
        val USER_ID = stringPreferencesKey(Constants.USER_ID_KEY)
        val USER_NAME = stringPreferencesKey(Constants.USER_NAME_KEY)
        val USER_EMAIL = stringPreferencesKey(Constants.USER_EMAIL_KEY)
        val USER_ROLE = stringPreferencesKey(Constants.USER_ROLE_KEY)
        val IS_LOGGED_IN = booleanPreferencesKey(Constants.IS_LOGGED_IN_KEY)
    }

    private val dataStore = context.dataStore

    // ==================== Token Operations ====================

    /**
     * Saves the authentication token.
     * @param token The Bearer token from login response
     */
    suspend fun saveToken(token: String) {
        dataStore.edit { preferences ->
            preferences[PrefsKeys.TOKEN] = token
        }
    }

    /**
     * Retrieves the authentication token as a Flow.
     * @return Flow<String?> The token or null if not found
     */
    fun getToken(): Flow<String?> = dataStore.data.map { preferences ->
        preferences[PrefsKeys.TOKEN]
    }

    /**
     * Retrieves the token synchronously (suspend).
     * Use this in repositories for single-shot access.
     */
    suspend fun getTokenSync(): String? {
        val preferences = dataStore.data.map { it[PrefsKeys.TOKEN] }
        return preferences.map { it }.collector()
    }

    /**
     * Checks if token exists.
     * @return Flow<Boolean> true if token is present
     */
    fun hasToken(): Flow<Boolean> = dataStore.data.map { preferences ->
        !preferences[PrefsKeys.TOKEN].isNullOrEmpty()
    }

    // ==================== User Information Operations ====================

    /**
     * Saves user information after successful login.
     */
    suspend fun saveUserInfo(
        userId: String,
        userName: String,
        userEmail: String,
        userRole: String
    ) {
        dataStore.edit { preferences ->
            preferences[PrefsKeys.USER_ID] = userId
            preferences[PrefsKeys.USER_NAME] = userName
            preferences[PrefsKeys.USER_EMAIL] = userEmail
            preferences[PrefsKeys.USER_ROLE] = userRole
            preferences[PrefsKeys.IS_LOGGED_IN] = true
        }
    }

    /**
     * Retrieves user ID as Flow.
     */
    fun getUserId(): Flow<String?> = dataStore.data.map { preferences ->
        preferences[PrefsKeys.USER_ID]
    }

    /**
     * Retrieves user name as Flow.
     */
    fun getUserName(): Flow<String?> = dataStore.data.map { preferences ->
        preferences[PrefsKeys.USER_NAME]
    }

    /**
     * Retrieves user email as Flow.
     */
    fun getUserEmail(): Flow<String?> = dataStore.data.map { preferences ->
        preferences[PrefsKeys.USER_EMAIL]
    }

    /**
     * Retrieves user role as Flow.
     */
    fun getUserRole(): Flow<String?> = dataStore.data.map { preferences ->
        preferences[PrefsKeys.USER_ROLE]
    }

    /**
     * Retrieves login status as Flow.
     */
    fun isLoggedIn(): Flow<Boolean> = dataStore.data.map { preferences ->
        preferences[PrefsKeys.IS_LOGGED_IN] ?: false
    }

    /**
     * Retrieves user role synchronously (suspend).
     * Use in navigation logic after login.
     */
    suspend fun getUserRoleSync(): String? {
        return dataStore.data.map { preferences ->
            preferences[PrefsKeys.USER_ROLE]
        }.collector()
    }

    // ==================== Cleanup Operations ====================

    /**
     * Clears all user data (logout).
     * Called when user logs out or token expires.
     */
    suspend fun clearAllData() {
        dataStore.edit { preferences ->
            preferences.clear()
        }
    }

    /**
     * Clears only the token (token refresh scenario).
     */
    suspend fun clearToken() {
        dataStore.edit { preferences ->
            preferences[PrefsKeys.TOKEN] = ""
            preferences[PrefsKeys.IS_LOGGED_IN] = false
        }
    }
}

/**
 * Helper collector function for Flow<T>.
 * This is a workaround for single-shot value extraction from Flow.
 */
private suspend fun <T> Flow<T>.collector(): T? {
    var result: T? = null
    this.collect { value ->
        result = value
    }
    return result
}

package com.saroj.lmsmobile.utils
/** * Global constants for the SLMS Mobile App. * Includes API endpoints, request codes, timeout values, and app settings. */ object Constants {
// ==================== API Configuration ==================== // Base URL for API requests - Change based on emulator/device const val BASE_URL = "http://10.0.2.2:8000/api/"
// API Endpoints object Endpoints { // Auth const val LOGIN = "login" const val LOGOUT = "logout" const val PROFILE = "profile" const val TEST_UNAUTHORIZED = "test-unauthorized"
// Books const val BOOKS = "books" const val BOOK_DETAIL = "books/{id}" const val SEARCH_BOOKS = "books/search" const val AVAILABLE_BOOKS = "books/available" const val BOOKS_BY_CATEGORY = "books/category/{category}"
// Students const val STUDENTS = "students" const val STUDENT_DETAIL = "students/{id}" const val SEARCH_STUDENTS = "students/search"
// Issues const val ISSUES = "issues" const val ISSUE_DETAIL = "issues/{id}" const val CREATE_ISSUE = "issues" const val RETURN_ISSUE = "issues/return/{id}" const val STUDENT_ISSUES = "issues/student/{studentId}"
// Dashboard const val DASHBOARD = "dashboard"
// Overdue const val OVERDUE = "overdue"
// Fines const val FINES = "fines" const val STUDENT_FINES = "fines/student/{id}" }
// ==================== DataStore Keys ==================== const val TOKEN_KEY = "access_token" const val USER_ID_KEY = "user_id" const val USER_NAME_KEY = "user_name" const val USER_EMAIL_KEY = "user_email" const val USER_ROLE_KEY = "user_role" const val IS_LOGGED_IN_KEY = "is_logged_in"
// ==================== User Roles ==================== const val ROLE_ADMIN = "admin" const val ROLE_STAFF = "staff" const val ROLE_STUDENT = "student"
// ==================== Network Configuration ==================== const val NETWORK_TIMEOUT = 30L // seconds const val CONNECT_TIMEOUT = 15L // seconds const val READ_TIMEOUT = 30L // seconds
// ==================== HTTP Headers ==================== const val AUTHORIZATION_HEADER = "Authorization" const val BEARER_TOKEN_PREFIX = "Bearer " const val ACCEPT_HEADER = "Accept" const val CONTENT_TYPE_HEADER = "Content-Type" const val APPLICATION_JSON = "application/json"
// ==================== HTTP Status Codes ==================== const val HTTP_OK = 200 const val HTTP_CREATED = 201 const val HTTP_UNAUTHORIZED = 401 const val HTTP_FORBIDDEN = 403 const val HTTP_NOT_FOUND = 404 const val HTTP_UNPROCESSABLE_ENTITY = 422 const val HTTP_SERVER_ERROR = 500
// ==================== Error Messages ==================== const val ERROR_NO_INTERNET = "No internet connection. Please check your network." const val ERROR_UNAUTHORIZED = "Your session has expired. Please login again." const val ERROR_FORBIDDEN = "You don't have permission to access this resource." const val ERROR_NOT_FOUND = "Resource not found." const val ERROR_VALIDATION = "Please check your input and try again." const val ERROR_SERVER = "Server error occurred. Please try again later." const val ERROR_UNKNOWN = "An unknown error occurred. Please try again."
// ==================== UI Configuration ==================== // Animation durations (milliseconds) const val ANIMATION_DURATION_SHORT = 300L const val ANIMATION_DURATION_MEDIUM = 500L const val ANIMATION_DURATION_LONG = 1000L
// Fragment and Activity transition durations const val FRAGMENT_TRANSITION_DURATION = 300
// Splash screen duration const val SPLASH_SCREEN_DURATION = 2000L
// ==================== Request Codes ==================== const val REQUEST_CODE_LOGIN = 1001 const val REQUEST_CODE_LOGOUT = 1002 const val REQUEST_CODE_PROFILE = 1003 const val REQUEST_CODE_BOOKS = 1004 const val REQUEST_CODE_STUDENTS = 1005
// ==================== Pagination ==================== const val DEFAULT_PAGE_SIZE = 20 const val FIRST_PAGE = 1
// ==================== Shared Preferences / DataStore ==================== const val PREFS_NAME = "lms_mobile_app" const val PREFS_MODE = android.content.Context.MODE_PRIVATE
// ==================== Bundle Keys ==================== const val KEY_BOOK_ID = "book_id" const val KEY_STUDENT_ID = "student_id" const val KEY_ISSUE_ID = "issue_id" const val KEY_FINE_ID = "fine_id" const val KEY_USER_ROLE = "user_role" const val KEY_MESSAGE = "message" const val KEY_ERROR = "error" }

